        "label": "fact",
        "sourceUrl": "https://erwinfab.com/about/",
        "quote": "With over 28 years of expertise—and 32 years in business since April 4, 1993—we specialize in structural steel fabrication"
      }
    ]
  },
  "industry": {
    "industry": "Custom Metal Fabrication and Welding",
    "activities": [
      "Custom metal fabrication",
      "Structural steel fabrication",
      "Welding services",
      "Sheet metal fabrication",
      "Aluminum and stainless steel fabrication",
      "Metal laser cutting",
      "Ornamental metals, gates, and fences",
      "Custom metal range hoods, countertops, cabinets, sinks, and steel tanks"
    ],
    "claims": [
      {
        "statement": "The shop provides custom metal fabrication, structural steel fabrication, welding, sheet metal, aluminum and stainless fabrication, laser cutting, ornamental metals, countertops, gates, and fences.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "We provide custom metal fabrication, structural steel fabrication, welding, sheet metal, aluminum and stainless fabrication, metal laser cutting, ornamental metals, custom countertops, gates, and fences."
      },
      {
        "statement": "The company fabricates custom metal pieces in its Nampa shop for both residential and commercial clients, rather than operating as a residential HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://erwinfab.com/services/metal-fabrication-nampa-id/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://erwinfab.com/",
    "claims": [
      {
        "statement": "The business's regular shop hours are Monday through Thursday from 7:00 AM to 4:30 PM, and it is closed Friday through Sunday.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/contact/",
        "quote": "Mon–Thu 7:00 AM–4:30 PM Fri–Sun Closed"
      },
      {
        "statement": "The company serves Nampa, Caldwell, Meridian, Eagle, Star, Boise, Garden City, Kuna, McCall, Cascade, and Emmett.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "we deliver tight fits, clean welds, and dependable handoff for clients in Nampa, Caldwell, Meridian, Eagle, Star, Boise, Garden City, Kuna, McCall, Cascade, and Emmett."
