        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "Brightbeam SEO Boise"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The company describes itself as a metal fabricator, aluminum welder, sheet metal contractor, and welder.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "We are a metal fabricator, aluminum welder, sheet metal contractor, and welder equipped for a wide range of custom jobs."
      }
    ],
    "limitations": "No state contractor license numbers, welding certification numbers, or business registration numbers are displayed on the pages read."
  },
