    {
      "product": "reCAPTCHA",
      "purpose": "Spam and bot protection on website quote request forms",
      "evidence": {
        "statement": "The website quote forms state that the site is protected by reCAPTCHA.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "This site is protected by reCAPTCHA and the Google Privacy Policy and Terms of Service apply."
      }
    },
    {
      "product": "googletagmanager.com iframe",
      "purpose": "Website tag management and analytics tracking",
      "evidence": {
        "statement": "The website loads a frame from googletagmanager.com with ID GTM-WZ4BLQFV.",
        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "https://www.googletagmanager.com/ns.html?id=GTM-WZ4BLQFV"
      }
    },
    {
      "product": "google.com/maps/embed iframe",
      "purpose": "Embedded location map on website pages",
      "evidence": {
