        "label": "fact",
        "sourceUrl": "https://erwinfab.com/",
        "quote": "https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2889.7097796330045!2d-116.53635942382645!3d43.59176107110502!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x54ae4dada5b39b33%3A0xbc121a038de1cdc4!2sErwin%20Custom%20Fabrication!5e0!3m2!1sen!2sph!4v1786593383385!5m2!1sen!2sph"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Customers request quotes by calling, emailing, or submitting a basic web form with Name, Email, Phone, and Message, or by bringing drawings, photos, and measurements during shop hours.",
      "label": "fact",
      "sourceUrl": "https://erwinfab.com/services/metal-fabrication-nampa-id/",
      "quote": "How do I get a metal fabrication quote in Nampa? + Call [redacted] or email [redacted] with drawings, photos, or measurements."
    },
    {
      "statement": "The shop is closed Friday through Sunday, meaning inquiries arriving after 4:30 PM Thursday wait until Monday morning unless monitored.",
      "label": "inference",
      "sourceUrl": "https://erwinfab.com/contact/",
      "quote": null
    }
  ],
  "problems": [
    {
      "problem": "Potential delay in responding to weekend or after-hours quote requests while the shop is closed Friday through Sunday.",
      "label": "hypothesis",
      "basis": "The shop's stated hours are Monday through Thursday 7:00 AM to 4:30 PM and closed Friday through Sunday, and no automated instant-reply or chat system is visible on the public site."
    },
    {
      "problem": "Manual back-and-forth to collect drawings, measurements, and photos when prospects initially submit only a text message via the website quote form.",
      "label": "hypothesis",
      "basis": "The website quote form includes only Name, Email, Phone, and Message fields without a file upload field, whereas the service page notes that drawings, photos, and field sizes are needed for quoting."
    }
  ],
  "existingSolutions": [
    {
      "solution": "Standard web form file upload field and automated email autoresponder via existing website or email provider",
      "addresses": "Collecting drawings/photos upfront and acknowledging inquiries submitted outside Monday–Thursday shop hours",
      "alreadyOwned": false
    },
    {
      "solution": "Job-shop ERP/estimating software (such as JobBOSS, ECI M1, or QuickBooks with job costing)",
      "addresses": "Quote tracking and shop scheduling for custom metal fabrication",
      "alreadyOwned": false
    }
  ],
